'use strict';
window.PLACE_STORIES_KO={
gyeongbok:{title:'다시 돌아온 궁궐, 경복궁',theme:'왕의 권위, 궁중의 삶, 그리고 복원',chapters:[
{title:'01 · 새로운 나라의 얼굴',text:'사진을 찍기 전에, 잠깐 고개를 들어 궁궐의 크기를 느껴보세요. 이곳은 새로운 나라가 어떤 모습으로 보이고 싶었는지를 보여주는 공간이었습니다. 조선은 1392년에 세워졌고, 그로부터 3년 뒤인 1395년에 중심 궁궐인 경복궁이 들어섭니다. 단순히 왕이 살던 집이라기보다, 새 왕조의 얼굴이라고 생각해보면 좋겠습니다. 넓은 마당과 거듭 이어지는 문을 바라보세요. 건물들이 중심을 향해 시선을 모으는 모습이 느껴지나요? 궁궐을 볼 때는 이런 질문을 던져보세요. 무엇을 먼저 보게 만들고, 무엇은 깊숙이 감추어 두었을까. 건물의 이름을 외우는 것보다 공간을 이해하는 데 도움이 됩니다.'},
{title:'02 · 역사 속의 긴 빈자리',text:'오래전 모습이 그대로 남아 있는 것처럼 보이지만, 경복궁의 역사에는 긴 빈자리가 있습니다. 1592년 임진왜란 때 불타버린 뒤 곧바로 다시 지어진 것이 아니거든요. 270여 년이 지나서야 대규모 중건이 이루어졌고, 1867년에 완성됩니다. 이후 일제강점기의 훼손을 겪었고, 현대에 들어 복원이 이어졌습니다. 그러니 지금 눈앞의 궁궐은 어느 한 시대가 고스란히 멈춰 있는 풍경은 아닙니다. 사라지고, 다시 세우고, 되찾는 시간이 겹쳐 있는 장소입니다. 그렇게 바라보면, 화려한 왕실 건축 뒤로 이 공간을 기억하려는 사람들의 노력이 함께 보이기 시작합니다.'},
{title:'03 · 근정전의 위엄, 경회루의 환대',text:'두 이름을 기억해보세요. 근정전과 경회루입니다. 근정전에서는 즉위식과 외국 사신 접견 같은 중요한 의식이 열렸습니다. 이름에도 부지런히 정사를 돌본다는 의미가 담겨 있지요. 격식을 갖춘 사람들이 왕을 마주하는 장면을 상상해보세요. 왜 건물이 이토록 당당한 크기로 서 있는지 조금은 이해할 수 있습니다. 경회루는 또 다른 얼굴입니다. 연못 곁에서 왕과 신하가 연회를 열고 외국 사신을 대접하던 공간이지요. 물과 건물이 어우러지는 모습을 눈여겨보세요. 한쪽이 권위를 드러낸다면, 다른 쪽은 환대의 분위기를 만듭니다. 두 공간을 함께 보면 궁궐이 건물들의 모음이 아니라, 서로 다른 왕실의 일상이 펼쳐지던 무대였다는 사실이 느껴집니다.'}
]},
bukchon:{title:'오래된 지붕 아래, 의외로 근대적인 이야기',theme:'한옥, 일상, 그리고 변하는 도시',chapters:[
{title:'01 · 엽서 같은 풍경 너머',text:'지붕이 이어지는 선을 천천히 바라보세요. 북촌은 시간이 멈춘 동네처럼 느껴지지만, 실제 역사는 조금 더 복잡합니다. 궁궐 사이에 자리한 위치는 오래된 서울과 연결되지만, 오늘날처럼 한옥이 어깨를 맞댄 골목은 큰 땅이 작은 집터로 나뉘던 근대의 변화와도 관련이 있습니다. 전통적인 집의 형태가 변화하는 도시 안에서 새롭게 쓰인 것이지요. 그 두 시간이 겹쳐 있다는 점이 북촌을 더 흥미롭게 만듭니다.'},
{title:'02 · 세트장이 아니라, 살아 있는 동네',text:'서울시의 북촌 이야기는 정세권이라는 인물과 1920~1930년대 도시형 한옥의 건설을 소개합니다. 이 집들은 막연히 떠올리는 조선시대의 풍경만이 아니라, 커져 가는 도시의 생활과도 연결되어 있습니다. 문턱과 담장, 처마를 눈여겨보세요. 좁은 골목에서도 집 안의 사적인 공간을 지키려는 구성이 보입니다. 그리고 가장 중요한 사실은 지금도 누군가가 이 문 안에서 살아간다는 것입니다. 작은 목소리로 풍경을 즐겨주세요. 계속 이어지는 일상 자체가 이 동네의 역사이기도 하니까요.'}
]},
louvre:{title:'그림보다 먼저, 요새가 있었다',theme:'왕과 혁명, 그리고 공간의 변화',chapters:[
{title:'01 · 건물부터 하나의 전시품으로',text:'작품을 떠올리기 전에, 건물 자체를 첫 번째 전시품처럼 바라보세요. 루브르는 1190년 무렵 필리프 2세 때 요새로 시작했습니다. 처음부터 미술품을 보여주기 위한 장소가 아니라, 방어를 위한 공간이었던 것입니다. 이후 여러 시대를 거치며 왕궁으로 바뀌고 확장되었지요. 주변을 바라보며 이 두 장면을 함께 떠올려보세요. 도시를 지키던 요새가 왕의 권력을 드러내는 궁전으로 변해 가는 모습 말입니다.'},
{title:'02 · 새로운 관객을 맞이하다',text:'프랑스혁명 시기인 1793년, 루브르는 박물관으로 문을 엽니다. 왕실의 공간에 새로운 공공의 역할이 생긴 것이지요. 오늘날에는 유명한 작품을 향해 서둘러 걸어가기 쉽습니다. 하지만 잠시만 시간을 내어 안뜰과 길게 뻗은 건물의 규모를 느껴보세요. 전시실에 들어가기 전부터, 이 건축물은 권력이 어떻게 바뀌어 왔는지를 이야기하고 있습니다.'}
]},
orsay:{title:'이 미술관에 기차가 도착하던 시절',theme:'근대의 여행과 건물의 두 번째 삶',chapters:[
{title:'01 · 도착의 순간을 상상해보세요',text:'이 공간을 미술관 관람객 대신 여행객들이 채우고 있다고 상상해보세요. 오르세 역은 1900년 만국박람회에 맞추어 문을 열었고, 프랑스 남서부에서 파리로 오는 열차를 맞이했습니다. 거대한 내부를 바라보면, 파리에 도착하는 순간을 특별하게 만들어주는 건축이었다는 생각이 듭니다.'},
{title:'02 · 작품을 품는 새로운 역할',text:'시간이 흐른 뒤 역은 다른 역할을 얻습니다. 오르세 미술관은 1986년 12월 대중에게 문을 열었습니다. 기차역 건물을 계속 사용하면서, 예술을 만나는 장소로 바꾼 것입니다. 그래서 이곳의 관람에는 두 겹의 즐거움이 있습니다. 눈앞의 작품을 보는 즐거움, 그리고 그 작품을 감싸고 있는 건물을 읽는 즐거움이지요. 가끔은 고개를 들어보세요. 오르세에서는 작품 바깥의 공간도 자기만의 이야기를 들려줍니다.'}
]},
eiffel:{title:'계속 서 있을 이유가 필요했던 탑',theme:'공학, 실험, 그리고 전파',chapters:[
{title:'01 · 영원히 남을 예정은 아니었다',text:'에펠탑 없는 파리를 상상하기는 어렵지요. 하지만 1889년 만국박람회를 위해 문을 열었을 때, 이 탑의 미래가 보장되어 있었던 것은 아닙니다. 귀스타브 에펠에게 주어진 사용권의 기간은 20년이었습니다. 놀라운 구조물을 어떻게 세우느냐만큼이나, 왜 계속 남겨두어야 하느냐가 중요한 문제가 된 것이지요.'},
{title:'02 · 눈에 보이지 않는 역사',text:'과학 실험과 무선 통신은 그 답을 마련하는 데 기여했습니다. 탑의 높이는 전파를 보내는 데 유용했고, 이런 쓰임새는 에펠탑이 살아남는 데 힘이 되었습니다. 다시 위를 올려다보세요. 익숙한 철골의 윤곽은 이야기의 절반입니다. 나머지 절반은 눈에 보이지 않는 전파를 타고 공중으로 뻗어 나갔습니다. 아름다운 상징물인 동시에, 실제로 쓰임이 있는 구조물이었던 셈이지요.'}
]},
tuileries:{title:'왕실의 정원이 모두의 쉼터가 되기까지',theme:'정원을 설계하는 시선',chapters:[
{title:'01 · 위에서 바라보는 정원',text:'의자에 앉기 전에, 정원의 긴 선들을 먼저 바라보세요. 튈르리는 왕실의 공간에서 공공의 정원으로 변화했습니다. 궁전 가까이의 격식 있는 정원은 창문에서 내려다보는 모습도 고려해 설계되었습니다. 정원을 직접 걷는 장소이면서 동시에, 위에서 바라보는 하나의 구성으로 생각한 것이지요.'},
{title:'02 · 잠시 멈추는 것도 여행',text:'길과 빈 공간, 나무들이 어떻게 시선을 이끄는지 살펴보세요. 그리고 같은 공간을 사람들이 오늘 어떻게 쓰는지도 보세요. 대화를 나누거나, 조용히 앉거나, 미술관과 미술관 사이에서 잠깐 쉬어갑니다. 다음 명소로 서두르지 않아도 도시를 충분히 경험할 수 있습니다. 이곳의 역사는 정원의 배치에도 있고, 한때 왕실의 풍경이었던 곳이 모두의 일상적인 쉼터가 된 변화 속에도 있습니다.'}
]}
};
